    "This removes it for all workspaces on this site. You can restore it from the Trash for 60 days.": "يؤدي هذا إلى إزالتها من جميع مساحات العمل في هذا الموقع. يمكنك استعادتها من سلة المهملات لمدة 60 يومًا.",
