    "Until then, the downloaded packages on the Downloaded tab are the ones Tovu ships.": "그때까지는 다운로드됨 탭의 다운로드된 패키지가 Tovu에 포함된 패키지입니다.",
    "An installed plugin sits inert until you enable it. Enabling one puts its skills in the assistant's prompt for every run.": "설치된 플러그인은 활성화하기 전까지 동작하지 않습니다. 활성화하면 실행할 때마다 해당 스킬이 어시스턴트의 프롬프트에 들어갑니다.",
    "No Agent Plugins are installed in this workspace.": "이 워크스페이스에 설치된 에이전트 플러그인이 없습니다.",
    "Agent Plugin Marketplace": "에이전트 플러그인 마켓플레이스",
    "A future place to discover portable Agent Plugins.": "휴대 가능한 에이전트 플러그인을 찾아볼 향후 공간입니다.",
    "Nothing to browse yet": "아직 둘러볼 항목이 없습니다",
    "Marketplace is planned for a future release. Tovu does not fetch, install, or list marketplace packages yet.": "마켓플레이스는 향후 릴리스에서 제공될 예정입니다. Tovu는 아직 마켓플레이스 패키지를 가져오거나 설치하거나 나열하지 않습니다.",
    "Read the package format": "패키지 형식 읽기",
    "Package format:": "패키지 형식:",
    "Uninstall is unavailable: these packages ship with Tovu and are restored on the next restart.": "제거할 수 없습니다: 이 패키지들은 Tovu와 함께 제공되며 다음 재시작 시 복원됩니다.",
    "No plugins are enabled for this site.": "이 사이트에 활성화된 플러그인이 없습니다.",
    "Enabled plugins extend what this site can do.": "활성화된 플러그인은 이 사이트의 기능을 확장합니다.",
    "Built-in plugins ship with Tovu itself and have no on-disk files to remove.": "기본 제공 플러그인은 Tovu 자체와 함께 제공되며 제거할 디스크 파일이 없습니다.",
    "Turn a plugin off on Installed before removing it.": "플러그인을 제거하기 전에 설치됨에서 끄세요.",
    "Marketplace is planned for a future release. Tovu does not fetch, list, or install plugins from a marketplace yet.": "마켓플레이스는 향후 릴리스에서 제공될 예정입니다. Tovu는 아직 마켓플레이스에서 플러그인을 가져오거나 나열하거나 설치하지 않습니다.",
    "Install a plugin by placing its files in this site's plugin install directory.": "이 사이트의 플러그인 설치 디렉터리에 파일을 넣어 플러그인을 설치하세요.",
