    "Capabilities": "Можливості",
    "Hooks": "Хуки",
    "This plugin runs code with full access to this computer and every site on it.": "Цей плагін виконує код із повним доступом до цього комп’ютера та всіх сайтів на ньому.",
    "It stays off in every workspace until you turn it on.": "Він залишається вимкненим у всіх робочих просторах, доки ви його не ввімкнете.",
    // AW-7 Tier 1 + plugin-conflicts install preview (2026-10-04).
    "Content type": "Тип контенту",
    "Content types": "Типи контенту",
    "This plugin has no code; nothing in it runs on this computer. Turning it on only adds what it declares.": "Цей плагін не містить коду; нічого з нього не виконується на цьому комп’ютері. Увімкнення лише додає те, що він оголошує.",
    "Already in use in this workspace (other workspaces are checked when you turn it on there):": "Уже використовується в цьому робочому просторі (інші простори перевіряються, коли ви вмикаєте його там):",
