    "Local folder installs are disabled on this server.": "Встановлення з локальних папок вимкнено на цьому сервері.",
    "Turn this plugin off in every workspace before installing.": "Вимкніть цей плагін у всіх робочих просторах перед встановленням.",
    "Installation conflicts with an existing plugin. Check its version and replacement option.": "Встановлення конфліктує з наявним плагіном. Перевірте версію та параметр заміни.",
    "Invalid plugin package. Check its manifest, integrity and folder.": "Недійсний пакет плагіна. Перевірте маніфест, цілісність і папку.",
