    // Agent Plugins / Plugins tab copy previously translated only in `es`
    "Integrations": "Інтеграції",
    "Downloaded Agent Plugins": "Завантажені плагіни агентів",
    "Every package downloaded to this workspace.": "Усі пакети, завантажені в цей робочий простір.",
    "No Agent Plugins are enabled for this workspace.": "У цьому робочому просторі не ввімкнено жодного плагіна агентів.",
    "These plugins are enabled. Their skills reach the assistant's prompt on every run.": "Ці плагіни ввімкнені. Їхні навички потрапляють до підказки асистента під час кожного запуску.",
    "Until then, the downloaded packages on the Downloaded tab are the ones Tovu ships.": "До того часу завантажені пакети на вкладці «Завантажено» — це ті, що постачаються з Tovu.",
    "An installed plugin sits inert until you enable it. Enabling one puts its skills in the assistant's prompt for every run.": "Встановлений плагін бездіяльний, доки ви його не ввімкнете. Увімкнений плагін додає свої навички до підказки асистента під час кожного запуску.",
    "No Agent Plugins are installed in this workspace.": "У цьому робочому просторі не встановлено жодного плагіна агентів.",
    "Agent Plugin Marketplace": "Маркетплейс плагінів агентів",
