    "The .zip is too big once unpacked: at most 4096 files, 16 MiB per file, 64 MiB in all.": ".zip ใหญ่เกินไปเมื่อแตกไฟล์: สูงสุด 4096 ไฟล์ ไฟล์ละ 16 MiB รวม 64 MiB",
