    "An installed plugin sits inert until you enable it. Enabling one puts its skills in the assistant's prompt for every run.": "इंस्टॉल किया गया प्लगिन तब तक निष्क्रिय रहता है जब तक आप उसे सक्षम नहीं करते। सक्षम करने पर उसके स्किल हर रन में असिस्टेंट के प्रॉम्प्ट में जुड़ जाते हैं।",
