    "Built-in plugins ship with Tovu itself and have no on-disk files to remove.": "बिल्ट-इन प्लगिन स्वयं Tovu के साथ आते हैं और उनकी हटाने योग्य कोई डिस्क फ़ाइल नहीं होती।",
