    "No plugin.json found. Put plugin.json at the top of the .zip, or inside one folder.": "plugin.json পাওয়া যায়নি। plugin.json .zip-এর সবচেয়ে উপরের স্তরে বা একটি মাত্র ফোল্ডারের ভিতরে রাখুন।",
    "plugin.json is not a valid Agent Plugin manifest.": "plugin.json কোনো বৈধ এজেন্ট প্লাগইন ম্যানিফেস্ট নয়।",
    "This file is not a readable .zip.": "এই ফাইলটি পড়া যায় এমন .zip নয়।",
    "A different plugin with this name is already installed.": "এই নামে আরেকটি প্লাগইন আগেই ইনস্টল করা আছে।",
    "The .zip is too big once unpacked: at most 4096 files, 16 MiB per file, 64 MiB in all.": "খোলার পর .zip খুব বড়: সর্বোচ্চ 4096টি ফাইল, প্রতি ফাইল 16 MiB, মোট 64 MiB।",
    "You don't have permission to install plugins.": "আপনার প্লাগইন ইনস্টল করার অনুমতি নেই।",
    "This .zip contains files or links that plugins may not include.": "এই .zip-এ এমন ফাইল বা লিংক আছে যা প্লাগইনে রাখা যায় না।",
    "Could not install the plugin. Try again.": "প্লাগইন ইনস্টল করা যায়নি। আবার চেষ্টা করুন।",
    "Choose one .zip file.": "একটি মাত্র .zip ফাইল বেছে নিন।",
