    "Installation conflicts with an existing plugin. Check its version and replacement option.": "ইনস্টলেশন বর্তমান প্লাগইনের সঙ্গে সংঘর্ষ করছে। সংস্করণ ও প্রতিস্থাপনের বিকল্প পরীক্ষা করুন।",
